const fs = require('fs');
const path = require('path');
const ROOT = '/vault';
const SKIP = new Set(['.obsidian', '.git', '.trash', 'Assets', 'Excalidraw', '90-launchCenter']);
const today = new Date();
today.setHours(0, 0, 0, 0);
const changed = [];

function walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (SKIP.has(entry.name) || entry.name.startsWith('.')) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) { walk(full); continue; }
    if (!entry.name.endsWith('.md')) continue;
    try {
      const st = fs.statSync(full);
      if (st.mtime >= today) changed.push(path.relative(ROOT, full));
    } catch (e) { /* iCloud 占位文件可能读不到，跳过 */ }
  }
}
walk(ROOT);
changed.sort();
const list = changed.slice(0, 50);
return [{ json: {
  count: changed.length,
  list,
  prompt: list.length === 0
    ? ''
    : `以下是今天知识库变更的 ${changed.length} 个文件（最多列 50）：\n${list.join('\n')}\n\n请用一句话（50 字内）总结今天库里的变化。`
} }];

const fs = require('fs');
const inbox = '/vault/99-Diary/n8n-提醒.md';
const now = new Date();
const y = now.getFullYear();
const m = String(now.getMonth() + 1).padStart(2, '0');
const d = String(now.getDate()).padStart(2, '0');
const reply = $json.reply || '';
const changed = $('收集今日变更').first().json;
const lines = [
  `\n## ${y}-${m}-${d} 库变更摘要`,
  '',
  `> 今日变更 ${changed.count} 个文件。摘要（${reply.startsWith('（mock') ? 'mock' : 'LLM'}）：`,
  '',
  reply,
  '',
  '<details><summary>文件清单</summary>',
  '',
  ...changed.list.map(f => `- ${f}`),
  '',
  '</details>',
  ''
];
fs.appendFileSync(inbox, lines.join('\n'));
return [{ json: { wrote: true, reply } }];
